import {products,finishes,money,getProduct,read,write,readBag,readSaved,addBag,subtotal,productImage} from './catalog.js';
import {createWatch} from './watch3d.js';
const $=selector=>document.querySelector(selector), $$=selector=>[...document.querySelectorAll(selector)];
const page=document.body.dataset.page;
const toast=message=>{const node=$('#pageToast');node.textContent=message;node.classList.add('show');clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>node.classList.remove('show'),3500);};
function updateCount(){const node=$('#pageBagCount');if(node)node.textContent=readBag().reduce((sum,item)=>sum+item.qty,0);}
function productCard(p){const saved=readSaved().includes(p.id);return `<article class="product-card"><div class="product-card-top"><span class="product-badge ${p.id==='ultra'?'featured':''}">${p.tag}</span><button class="wishlist-button ${saved?'saved':''}" data-save="${p.id}" aria-label="${saved?'Unsave':'Save'} ${p.name}" aria-pressed="${saved}">♡</button></div><a class="product-image-button" href="product.html?id=${encodeURIComponent(p.id)}" aria-label="Explore ${p.name}">${productImage(p)}</a><div class="product-info"><span class="product-subtitle">${p.subtitle}</span><h3><a href="product.html?id=${encodeURIComponent(p.id)}">${p.name}</a></h3><p class="product-description">${p.description}</p><div class="product-card-footer"><span class="product-price">${money(p.price)}<small>Inclusive of all taxes</small></span><button class="add-button" data-add="${p.id}" aria-label="Add ${p.name} to bag">+</button></div></div></article>`;}
let catalogFilter='all';
function renderShop(){const q=($('#catalogSearch')?.value||'').trim().toLowerCase(),sort=$('#catalogSort')?.value||'featured';let list=products.filter(p=>(catalogFilter==='all'||p.type===catalogFilter)&&[p.name,p.detail,p.case,p.type,p.madeFor,p.gps].join(' ').toLowerCase().includes(q));if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);$('#resultCount').textContent=`${list.length} ${list.length===1?'watch':'watches'}`;$('#pageProductGrid').innerHTML=list.map(productCard).join('')||'<div class="inner-empty"><h2>NO WATCHES FOUND.</h2><p>Try another search or choose a different category.</p><button class="button primary" id="clearFilters">Show all watches ↗</button></div>';}
function renderSaved(){const list=readSaved().map(getProduct).filter(Boolean);$('#pageProductGrid').innerHTML=list.map(productCard).join('');$('#savedEmpty').hidden=list.length>0;}
function renderProduct(){const id=new URLSearchParams(location.search).get('id'),p=getProduct(id);if(!p){$('#productPage').innerHTML='<div class="inner-empty"><h1>WATCH NOT FOUND.</h1><p>This model is not in the current collection.</p><a class="button primary" href="shop.html">Shop all watches ↗</a></div>';$('#relatedGrid').innerHTML=products.slice(0,3).map(productCard).join('');return;}
 document.title=`${p.name} | X EIGHT`;$('#crumbProduct').textContent=p.name;
 $('#productPage').innerHTML=`<section class="product-page-hero"><div class="product-gallery"><div class="product-3d-stage" id="product3d" role="img" aria-label="Interactive 3D preview of ${p.name}. Drag or use arrow keys to rotate." tabindex="0"></div><div class="product-view-tools"><span>↔ DRAG TO ROTATE</span><button id="productReset" class="mini-button">Reset view</button><button id="productFace" class="mini-button">Minimal dial</button><button id="productExplode" class="mini-button" aria-pressed="false">Exploded view</button></div></div><div class="product-page-copy"><p class="eyebrow accent-text">${p.tag} / ${p.type.toUpperCase()}</p><h1>${p.name.toUpperCase()}.</h1><p class="product-page-lede">${p.detail}</p><strong class="product-page-price">${money(p.price)}</strong><p class="price-caption">Inclusive of all taxes · Complimentary demo shipping</p><fieldset class="product-option"><legend>FINISH <span id="selectedFinish">${finishes[p.defaultColor]}</span></legend><div class="finish-options">${Object.entries(finishes).map(([key,label])=>`<button type="button" class="finish-option ${key===p.defaultColor?'active':''}" data-finish="${key}" aria-pressed="${key===p.defaultColor}"><i style="--swatch:${key==='graphite'?'#454a47':key==='titanium'?'#c7c6b8':'#dc7137'}"></i>${label}</button>`).join('')}</div></fieldset><fieldset class="product-option"><legend>STRAP SIZE</legend><div class="size-options"><button type="button" class="size-option" data-size="S/M" aria-pressed="false">S/M · 130–180 mm</button><button type="button" class="size-option active" data-size="M/L" aria-pressed="true">M/L · 160–210 mm</button></div></fieldset><div class="product-purchase"><button class="button primary" id="productAdd">Add to bag — ${money(p.price)} ↗</button><button class="product-save" id="productSave" aria-pressed="${readSaved().includes(p.id)}">${readSaved().includes(p.id)?'♥ Saved':'♡ Save'}</button></div><p class="product-caveat">Concept product. No real payment or shipping.</p></div></section><section class="product-specs-section"><div class="inner-heading"><p class="eyebrow accent-text">THE DETAILS</p><h2>BUILT FOR YOUR DAY.</h2></div><div class="product-specs-grid">${[['Case',p.case],['Display',p.display],['Brightness',p.brightness],['Battery',p.battery],['Water resistance',p.water],['Navigation',p.gps],['Weight',p.weight],['Made for',p.madeFor]].map(([label,value])=>`<div><span>${label}</span><strong>${value}</strong></div>`).join('')}</div></section>`;
 $('#relatedGrid').innerHTML=products.filter(x=>x.id!==p.id).slice(0,3).map(productCard).join('');let color=p.defaultColor,size='M/L',minimal=false,exploded=false;
 const viewer=createWatch($('#product3d'),{color,compact:true});
 $$('#productPage [data-finish]').forEach(button=>button.addEventListener('click',()=>{color=button.dataset.finish;viewer.setColor(color);$('#selectedFinish').textContent=finishes[color];$$('#productPage [data-finish]').forEach(x=>{x.classList.toggle('active',x===button);x.setAttribute('aria-pressed',x===button)});}));
 $$('#productPage [data-size]').forEach(button=>button.addEventListener('click',()=>{size=button.dataset.size;$$('#productPage [data-size]').forEach(x=>{x.classList.toggle('active',x===button);x.setAttribute('aria-pressed',x===button)});}));
 $('#productReset').onclick=()=>{viewer.reset();exploded=false;$('#productExplode').setAttribute('aria-pressed','false');$('#productExplode').classList.remove('active');};
 $('#productFace').onclick=()=>{minimal=!minimal;viewer.setFace(minimal?'minimal':'performance');$('#productFace').textContent=minimal?'Performance dial':'Minimal dial';};
 $('#productExplode').onclick=()=>{exploded=!exploded;viewer.setExploded(exploded);$('#productExplode').setAttribute('aria-pressed',String(exploded));$('#productExplode').classList.toggle('active',exploded);};
 $('#productAdd').onclick=()=>{if(addBag(p.id,color,size)){location.href='bag.html';}else toast('Maximum 10 of each watch configuration.');};
 $('#productSave').onclick=()=>{const list=readSaved(),next=list.includes(p.id)?list.filter(x=>x!==p.id):[...list,p.id];write('xeight-saved',next);$('#productSave').textContent=next.includes(p.id)?'♥ Saved':'♡ Save';$('#productSave').setAttribute('aria-pressed',String(next.includes(p.id)));toast(next.includes(p.id)?`${p.name} saved`:'Removed from saved watches');};
 window.addEventListener('pagehide',()=>viewer.destroy(),{once:true});
}
function renderCompare(){const rows=[['Price',p=>money(p.price)],['Made for',p=>p.madeFor],['Case',p=>p.case],['Display',p=>p.display],['Brightness',p=>p.brightness],['Battery',p=>p.battery],['Water resistance',p=>p.water],['Navigation',p=>p.gps],['Weight',p=>p.weight]];$('#pageCompare').innerHTML=`<thead><tr><th scope="col">X EIGHT<br>COLLECTION</th>${products.map(p=>`<th scope="col"><a href="product.html?id=${p.id}">${productImage(p)}<span>${p.name}</span></a></th>`).join('')}</tr></thead><tbody>${rows.map(([label,value])=>`<tr><th scope="row">${label}</th>${products.map(p=>`<td>${value(p)}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">Explore</th>${products.map(p=>`<td><a class="button primary" href="product.html?id=${p.id}">View ↗</a></td>`).join('')}</tr></tbody>`;}
function renderBag(){const bag=readBag(),target=$('#bagPage');if(!bag.length){target.innerHTML='<div class="inner-empty"><h2>YOUR BAG IS WAITING.</h2><p>Find a watch that belongs in your day.</p><a class="button primary" href="shop.html">Explore all watches ↗</a></div>';updateCount();return;}
 target.innerHTML=`<div class="bag-page-layout"><div class="bag-page-items">${bag.map((item,index)=>{const p=getProduct(item.id);return `<article class="bag-page-item"><a class="bag-page-image" href="product.html?id=${p.id}">${productImage(p)}</a><div><span class="eyebrow accent-text">${p.tag}</span><h2><a href="product.html?id=${p.id}">${p.name}</a></h2><p>${finishes[item.color]} · ${item.size}</p><div class="bag-item-actions"><div class="quantity-control"><button data-qty="${index}" data-delta="-1" aria-label="Decrease ${p.name} quantity" ${item.qty===1?'disabled':''}>−</button><span>${item.qty}</span><button data-qty="${index}" data-delta="1" aria-label="Increase ${p.name} quantity" ${item.qty===10?'disabled':''}>+</button></div><button class="text-remove" data-remove="${index}">Remove</button></div></div><strong>${money(p.price*item.qty)}</strong></article>`;}).join('')}</div><aside class="bag-page-summary"><p class="eyebrow accent-text">ORDER SUMMARY</p><div><span>Subtotal</span><strong>${money(subtotal(bag))}</strong></div><div><span>Shipping</span><strong>Complimentary</strong></div><div class="bag-total"><span>Total</span><strong>${money(subtotal(bag))}</strong></div><a class="button primary" href="checkout.html">Continue to demo checkout ↗</a><p>No payment will be collected.</p></aside></div>`;updateCount();}
function renderCheckout(){const bag=readBag();if(!bag.length){$('#checkoutPage').innerHTML='<div class="inner-empty"><h2>YOUR BAG IS EMPTY.</h2><p>Add a watch before trying the checkout.</p><a class="button primary" href="shop.html">Shop watches ↗</a></div>';return;}
 $('#checkoutPage').innerHTML=`<div class="checkout-content checkout-page-layout"><form class="checkout-form" id="pageCheckoutForm"><div class="demo-notice">Demo checkout. Use sample details. No payment, delivery or email will be sent.</div><h2>Delivery details</h2><div class="form-grid"><label class="form-field">First name<input name="firstName" required maxlength="50" autocomplete="given-name" placeholder="Alex"></label><label class="form-field">Last name<input name="lastName" required maxlength="50" autocomplete="family-name" placeholder="Morgan"></label><label class="form-field wide">Email address<input name="email" type="email" required maxlength="120" autocomplete="email" placeholder="alex@example.com"></label><label class="form-field wide">Mobile number<input name="phone" type="tel" required pattern="[6-9][0-9]{9}" maxlength="10" inputmode="numeric" title="Enter a 10-digit Indian mobile number starting with 6, 7, 8 or 9" placeholder="9876543210"></label><label class="form-field wide">Street address<input name="address" required minlength="5" maxlength="180" autocomplete="street-address" placeholder="123 Example Street"></label><label class="form-field">City<input name="city" required maxlength="70" autocomplete="address-level2" placeholder="Chennai"></label><label class="form-field">PIN code<input name="pin" required pattern="[1-9][0-9]{5}" maxlength="6" inputmode="numeric" title="Enter a valid 6-digit Indian PIN code" placeholder="600001"></label><label class="form-field wide">State / union territory<select name="state" required><option value="">Select state / territory</option>${['Andhra Pradesh','Delhi','Goa','Gujarat','Karnataka','Kerala','Maharashtra','Puducherry','Tamil Nadu','Telangana','Uttar Pradesh','West Bengal','Other Indian state or territory'].map(state=>`<option>${state}</option>`).join('')}</select></label></div><span class="option-label">PREVIEW PAYMENT METHOD</span><div class="payment-options"><label><input type="radio" name="payment" value="UPI" checked>UPI</label><label><input type="radio" name="payment" value="Card">Card</label><label><input type="radio" name="payment" value="COD">Pay on delivery</label></div><button class="button primary full-width" type="submit">Place demo order ↗</button><p class="secure-note">Delivery details are discarded after confirmation.</p></form><aside class="checkout-order"><h2>Your selection</h2>${bag.map(i=>`<div class="order-line"><span>${getProduct(i.id).name} × ${i.qty}<small>${finishes[i.color]} · ${i.size}</small></span><b>${money(getProduct(i.id).price*i.qty)}</b></div>`).join('')}<div class="coupon-form"><input id="pageCoupon" aria-label="Promo code" placeholder="Promo code" maxlength="30"><button type="button" id="pageCouponApply">Apply</button></div><p class="coupon-message" id="pageCouponMessage" role="status"></p><span class="coupon-hint">Try XEIGHT10 for 10% off.</span><div id="pageTotals"></div><p>Prices are sample amounts in Indian rupees.</p></aside></div>`;
 let discount=false;const totals=()=>{const sum=subtotal(bag),off=discount?Math.round(sum*.1):0;$('#pageTotals').innerHTML=`<div class="summary-row"><span>Subtotal</span><span>${money(sum)}</span></div>${off?`<div class="summary-row"><span>XEIGHT10 · 10% off</span><span>−${money(off)}</span></div>`:''}<div class="summary-row"><span>Shipping</span><small>Complimentary</small></div><div class="summary-row total"><span>Total</span><strong>${money(sum-off)}</strong></div>`;};totals();
 $('#pageCouponApply').onclick=()=>{discount=$('#pageCoupon').value.trim().toUpperCase()==='XEIGHT10';$('#pageCouponMessage').textContent=discount?'10% discount applied.':'That code isn’t valid. Try XEIGHT10.';totals();};
 $('#pageCheckoutForm').onsubmit=event=>{event.preventDefault();if(!event.target.reportValidity())return;const order={id:`XE-${Date.now().toString(36).toUpperCase()}`,date:new Date().toISOString(),items:bag.map(i=>({...i})),total:subtotal(bag)-(discount?Math.round(subtotal(bag)*.1):0),demo:true};write('xeight-last-demo-order',order);write('xeight-bag',[]);event.target.reset();updateCount();$('#checkoutPage').innerHTML=`<div class="confirmation checkout-success"><div class="confirm-icon">✓</div><p class="eyebrow accent-text">DEMO COMPLETE</p><h2>YOU’RE ALL SET.</h2><p>Your demo order is complete. No payment was collected and no product will be shipped.</p><div class="order-reference">${order.id} · ${money(order.total)}</div><p>Your demo receipt stays in this browser. Your delivery details have been discarded.</p><a class="button primary" href="shop.html">Keep exploring ↗</a></div>`;};
}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.save){const list=readSaved(),id=button.dataset.save,next=list.includes(id)?list.filter(x=>x!==id):[...list,id];write('xeight-saved',next);if(page==='saved')renderSaved();else if(page==='shop')renderShop();else if(page==='product'){$('#productSave')?.setAttribute('aria-pressed',String(next.includes(id)));}else if(page==='compare')renderCompare();toast(next.includes(id)?`${getProduct(id).name} saved`:'Removed from saved watches');return;}if(button.dataset.add){const p=getProduct(button.dataset.add);if(addBag(p.id,p.defaultColor)){updateCount();toast(`${p.name} added to bag`);}else toast('Maximum 10 of each watch configuration.');return;}if(button.dataset.filter){catalogFilter=button.dataset.filter;$$('#pageFilters button').forEach(x=>{x.classList.toggle('active',x===button);x.setAttribute('aria-pressed',String(x===button));});renderShop();return;}if(button.id==='clearFilters'){catalogFilter='all';$('#catalogSearch').value='';$$('#pageFilters button').forEach(x=>{x.classList.toggle('active',x.dataset.filter==='all');x.setAttribute('aria-pressed',String(x.dataset.filter==='all'));});renderShop();return;}if(button.dataset.qty){const bag=readBag(),item=bag[Number(button.dataset.qty)],qty=item.qty+Number(button.dataset.delta);if(qty>=1&&qty<=10){item.qty=qty;write('xeight-bag',bag);renderBag();}return;}if(button.dataset.remove){const bag=readBag();bag.splice(Number(button.dataset.remove),1);write('xeight-bag',bag);renderBag();}});
$('#pageMenuToggle').onclick=event=>{const open=$('.header nav').classList.toggle('open');event.currentTarget.setAttribute('aria-expanded',String(open));event.currentTarget.setAttribute('aria-label',open?'Close navigation':'Open navigation');};
updateCount();
switch(page){case 'shop':$('#catalogSearch').addEventListener('input',renderShop);$('#catalogSort').addEventListener('change',renderShop);renderShop();break;case 'product':renderProduct();break;case 'saved':renderSaved();break;case 'compare':renderCompare();break;case 'bag':renderBag();break;case 'checkout':renderCheckout();break;}
